#!/bin/bash
# run_array.sh — array SPICE simulation for any array_X<S>_<R>x<C> cell
#
# Usage:
#   ./run_array.sh --node <N> <cellname> [--pex] [--toggle <rate>]
#
# Examples:
#   ./run_array.sh --node 20 array_X4_2x2 --pex
#   ./run_array.sh --node 5  array_X8_64x8 --pex --toggle 0.25
#
# Reads <cell>.sp / <cell>.spef from TECH_<N>nm/<cell>/02_pex/ (gen_array.py
# + gds2spice.sh first).  The testbench (6-op sequence: WR1init / RD 1->1 /
# WRsame / WRtoggle / WR0fill / RD 1->0 at the slow 10 ns/op cadence) is
# generated by scripts/gen_array_tb.py; --toggle sets the fraction of
# columns that flip in the toggle-write op (default 1.0).  Results are
# checked/summarized by scripts/array_measures.py; each run dir also gets
# a meta.json so scripts/collect_array.py can build the dataset sheet.
#
# Run directory: TECH_<N>nm/<cell>/03_sim/<cell>_tr<rate>_v<V>_t<T>_<stamp>/

set -e
set -o pipefail

usage() {
    echo "Usage: $0 --node <20|16|10|7|5> <array_cellname> [--pex] [--toggle <0..1>]"
    echo "       [--vdd <V>] [--temp <C>]   (defaults: node.env nominal VDD/TEMP)"
    echo "  e.g.: $0 --node 20 array_X4_2x2 --pex --toggle 0.5 --vdd 0.85 --temp 85"
    exit 1
}
die() { echo "Error: $*" >&2; exit 1; }

normalize_node() {
    local n="${1%nm}"
    n=$((10#$n)) 2>/dev/null || die "Bad node spec: $1"
    printf "%02dnm" "$n"
}

# ── Argument parsing ─────────────────────────────────────────────────────────

NODE=""
PEX=0
TOGGLE=1.0
VDD_OVR=""
TEMP_OVR=""
POS=()
while [ $# -gt 0 ]; do
    case "$1" in
        --node)   NODE="$2"; shift 2 ;;
        --pex)    PEX=1; shift ;;
        --toggle) TOGGLE="$2"; shift 2 ;;
        --vdd)    VDD_OVR="$2"; shift 2 ;;
        --temp)   TEMP_OVR="$2"; shift 2 ;;
        -h|--help) usage ;;
        *) POS+=("$1"); shift ;;
    esac
done

[ -n "$NODE" ]       || usage
[ ${#POS[@]} -ge 1 ] || usage
CELLNAME="${POS[0]}"
[[ "$CELLNAME" =~ ^array_X([0-9]+)_([0-9]+)x([0-9]+)$ ]] \
    || die "cellname must match array_X<S>_<R>x<C>: $CELLNAME"
WD="${BASH_REMATCH[1]}"; ROWS="${BASH_REMATCH[2]}"; COLS="${BASH_REMATCH[3]}"

# ── Node environment ─────────────────────────────────────────────────────────

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
SRAM_DIR="$(realpath "$SCRIPT_DIR/..")"
NN="$(normalize_node "$NODE")"

eval "$(python3 "$SRAM_DIR/spice/scripts/tech_paths.py" --node "$NODE")" \
    || die "tech_paths.py failed for node $NODE"
[ -n "$TECH_SRAM" ] || die \
"node $NODE has no SRAM library (no sramdir in tech_libs/catalog.json)"
[ -f "$TECH_SRAM/node.env" ] || die "Missing $TECH_SRAM/node.env"
# shellcheck disable=SC1091
source "$TECH_SRAM/node.env"

# PVT overrides: node.env VDD is the node's nominal; voltage_offset_V in the
# dataset sheet is measured against it
VDD_NOM="$VDD"
[ -n "$VDD_OVR" ]  && VDD="$VDD_OVR"
[ -n "$TEMP_OVR" ] && TEMP="$TEMP_OVR"
VOFFSET="$(awk -v a="$VDD" -v b="$VDD_NOM" 'BEGIN{printf "%.4g", a-b}')"

CFG_DIR="$SRAM_DIR/TECH_$NN/$CELLNAME"
OUT_DIR="$CFG_DIR/02_pex"
GEN_TB="$SCRIPT_DIR/scripts/gen_array_tb.py"
MEASURES="$SCRIPT_DIR/scripts/array_measures.py"
TIE_BULK="$SRAM_DIR/spice/scripts/tie_bulk.py"

for f in "$GEN_TB" "$MEASURES" "$TIE_BULK"; do
    [ -f "$f" ] || die "not found: $f"
done
for f in nmos1.inc pmos1.inc; do
    [ -s "$TECH_SRAM/models/$f" ] || die "Missing/empty model card: $TECH_SRAM/models/$f"
done

[ -f "$OUT_DIR/${CELLNAME}.sp" ] || die "Not found: $OUT_DIR/${CELLNAME}.sp (run gds2spice.sh first)"
if [ "$PEX" = "1" ]; then
    [ -f "$OUT_DIR/${CELLNAME}.spef" ] || die "Not found: $OUT_DIR/${CELLNAME}.spef (run gds2spice.sh first)"
fi
AREA_JSON="$CFG_DIR/01_gds/${CELLNAME}.json"

# ── Run directory ────────────────────────────────────────────────────────────

TIMESTAMP="$(date +%Y%m%d_%H%M%S)"
RUN_DIR="$CFG_DIR/03_sim/${CELLNAME}_tr${TOGGLE}_v${VDD}_t${TEMP}_${TIMESTAMP}"
mkdir -p "$RUN_DIR"

echo "Node    : $NODE_NAME  (VDD=${VDD}V, TEMP=${TEMP}C)"
echo "Array   : $CELLNAME  (${ROWS} rows x ${COLS} cols, WD=X${WD}, toggle=${TOGGLE})"
echo "Run dir : $RUN_DIR"

# Tie bulk terminals (nmos1->VSS, pmos1->VDD) and copy to run directory
python3 "$TIE_BULK" "$OUT_DIR/${CELLNAME}.sp" "$RUN_DIR/${CELLNAME}.sp"
[ "$PEX" = "1" ] && ln -sfr "$OUT_DIR/${CELLNAME}.spef" "$RUN_DIR/${CELLNAME}.spef"
ln -sfn "$TECH_SRAM/models" "$RUN_DIR/models"
[ -f "$AREA_JSON" ] && cp "$AREA_JSON" "$RUN_DIR/area.json" \
    || echo "Warning: no $AREA_JSON (regenerate with current gen_array.py for area)"

BA_ARG=()
[ "$PEX" = "1" ] && BA_ARG=(--ba "${CELLNAME}.spef")
HDL_ARG=()
[ -n "${MODEL_HDL:-}" ] && HDL_ARG=(--hdl "$MODEL_HDL")

TB_FILE="$RUN_DIR/tb_${CELLNAME}.sp"
GEN_OUT="$(python3 "$GEN_TB" "$RUN_DIR/${CELLNAME}.sp" \
    --cellname "$CELLNAME" --vdd "$VDD" --temp "$TEMP" --node "$NODE_NAME" \
    --toggle-rate "$TOGGLE" "${BA_ARG[@]}" "${HDL_ARG[@]}" -o "$TB_FILE")"
echo "$GEN_OUT" | grep -v "^META "
META="$(echo "$GEN_OUT" | grep "^META ")" || die "gen_array_tb printed no META line"
read -r _ M_ROWS M_COLS M_RATE M_NT <<< "$META"

cat > "$RUN_DIR/meta.json" <<EOF
{
 "cell": "$CELLNAME", "node": "$NODE_NAME",
 "rows": $ROWS, "cols": $COLS, "wd": $WD,
 "${M_ROWS%%=*}_tb": ${M_ROWS#*=}, "${M_COLS%%=*}_tb": ${M_COLS#*=},
 "${M_RATE%%=*}": ${M_RATE#*=}, "${M_NT%%=*}": ${M_NT#*=},
 "vdd_V": $VDD, "temperature_C": $TEMP, "pex": $PEX,
 "transistor": "${FLAVOR:-hp}", "corner": "${CORNER:-TT}",
 "voltage_offset_V": ${VOFFSET:-0.0},
 "flow_run_id": "${CELLNAME}_tr${TOGGLE}_v${VDD}_t${TEMP}_${TIMESTAMP}"
}
EOF

cd "$RUN_DIR"

if [ "$PEX" = "1" ]; then
    SUFFIX="_pex"
    echo "=== Post-layout: $CELLNAME (SPEF back-annotation via ba_file) ==="
else
    SUFFIX=""
    echo "=== Pre-layout: $CELLNAME ==="
fi
hspice "$TB_FILE" -o "tb_${CELLNAME}${SUFFIX}" 2>&1 | tee "sim.log" \
    | grep -Ei "error|warning: *(too|conv)|aborted|\*\*\*" || true

MT0="tb_${CELLNAME}${SUFFIX}.mt0"
[ -f "$MT0" ] || die "no $MT0 produced — see $RUN_DIR/sim.log"
echo
PYTHONPATH="$SCRIPT_DIR/scripts" python3 "$MEASURES" "$MT0" --vdd "$VDD" \
    --rows "$ROWS" --cols "$COLS" -o "measures.csv"
echo "Results: $RUN_DIR"
